insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('morning-intention-sticky-note-page', 'Morning Intention Sticky Note Page', 'worksheet'::resource_kind, 'A page for choosing one small intention for the day and noting how it went.', 'Use it to help a client link a morning choice to an evening look-back.', array['Adults']::text[], 'Five minutes daily for a week', 'Ask the client to keep the intention concrete and small enough to notice. Review the evening notes together and look for what helped, not for a score. If an intention was missed, treat it as information about the day, not a failure.', '[{"id": "f0", "type": "textarea", "label": "My intention for today:"}, {"id": "f1", "type": "textarea", "label": "Where I will see the reminder:"}, {"id": "f2", "type": "textarea", "label": "One moment I acted on it:"}, {"id": "f3", "type": "textarea", "label": "What got in the way:"}, {"id": "f4", "type": "textarea", "label": "What I will carry into tomorrow:"}]'::jsonb, array['routine', 'reflection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('energy-map-of-the-week', 'Energy Map of the Week', 'worksheet'::resource_kind, 'A grid for marking when a client feels most and least energetic across a week.', 'Use it to find realistic times for hard tasks and rest.', array['Adults']::text[], 'One week', 'Hand it over a week before you plan any schedule changes. Clients often notice patterns by day and time that they had not named. Plan one task around a high point and one rest around a low point, and let the client decide what to adjust.', '[{"id": "f0", "type": "textarea", "label": "Times I felt most energetic:"}, {"id": "f1", "type": "textarea", "label": "Times I felt drained:"}, {"id": "f2", "type": "textarea", "label": "What I was doing at those times:"}, {"id": "f3", "type": "textarea", "label": "One task I could move to a high point:"}, {"id": "f4", "type": "textarea", "label": "One rest I could add at a low point:"}]'::jsonb, array['planning', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('choice-weighing-grid-with-values-lane', 'Choice Weighing Grid With Values Lane', 'worksheet'::resource_kind, 'A decision table with a column for what each choice says about what matters to the client.', 'Use it to help a client weigh a choice against their own values.', array['Adults']::text[], '30 minutes', 'Fill in the usual pros and cons first, then add the values column so the client sees what each option protects. Resist steering toward an answer. Some clients leave with a choice and some with a next question, and both are fine.', '[{"id": "f0", "type": "textarea", "label": "The decision in front of me:"}, {"id": "f1", "type": "textarea", "label": "Pros of choice one and choice two:"}, {"id": "f2", "type": "textarea", "label": "Cons of choice one and choice two:"}, {"id": "f3", "type": "textarea", "label": "The value each choice serves:"}, {"id": "f4", "type": "textarea", "label": "What I will do next, even if small:"}]'::jsonb, array['decisions', 'values']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('boundary-script-drafting-page', 'Boundary Script Drafting Page', 'worksheet'::resource_kind, 'A page for writing a short boundary statement before a hard conversation.', 'Use it to help a client put a limit into words they can say aloud.', array['Adults']::text[], '25 minutes', 'Have the client draft, then say the script aloud in session and adjust the wording until it sounds like them. Talk through how the other person might react and what the client will do if the limit is tested.', '[{"id": "f0", "type": "textarea", "label": "The limit I want to set:"}, {"id": "f1", "type": "textarea", "label": "Who I need to say it to:"}, {"id": "f2", "type": "textarea", "label": "My script in one or two sentences:"}, {"id": "f3", "type": "textarea", "label": "How they might respond:"}, {"id": "f4", "type": "textarea", "label": "What I will do if they push back:"}]'::jsonb, array['boundaries', 'communication']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('small-wins-receipt-sheet', 'Small Wins Receipt Sheet', 'worksheet'::resource_kind, 'A receipt-style page for recording three small things done each day.', 'Use it to help a client notice effort that usually goes unmentioned.', array['Adults']::text[], 'Five minutes daily for two weeks', 'Some clients discount anything small, so agree in advance that a win can be as plain as making a call or washing a dish. Read the receipts back at the next visit and ask which entry felt most like them.', '[{"id": "f0", "type": "textarea", "label": "Win one today:"}, {"id": "f1", "type": "textarea", "label": "Win two today:"}, {"id": "f2", "type": "textarea", "label": "Win three today:"}, {"id": "f3", "type": "textarea", "label": "What it took to do them:"}, {"id": "f4", "type": "textarea", "label": "What I would tell a friend who did these:"}]'::jsonb, array['strengths', 'tracking']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('prediction-versus-outcome-table', 'Prediction Versus Outcome Table', 'cbt'::resource_kind, 'A two-column table for writing what a client expects and what happened.', 'Use it to help a client compare predictions with what actually occurred.', array['Adults']::text[], 'One week', 'Choose one prediction that can be tested in daily life. The client records the guess and a confidence rating before, and the result after. Review the gap together, noting that a single outcome is information and not proof either way.', '[{"id": "f0", "type": "textarea", "label": "What I predicted would happen:"}, {"id": "f1", "type": "textarea", "label": "How sure I was, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What actually happened:"}, {"id": "f3", "type": "textarea", "label": "What I notice about the difference:"}, {"id": "f4", "type": "textarea", "label": "The next prediction I will test:"}]'::jsonb, array['predictions', 'behavioral experiment']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('thinking-trap-spotter-card-sort', 'Thinking Trap Spotter Card Sort', 'cbt'::resource_kind, 'A card sort for matching everyday thoughts to common thinking traps.', 'Use it to help a client name thinking traps in their own words.', array['Adults']::text[], '25 minutes', 'Write the client''s own thoughts on cards and sort them together under trap names such as mind reading or all-or-nothing. A thought can sit under more than one. The aim is a shared vocabulary, not a perfect label.', '[{"id": "f0", "type": "textarea", "label": "A thought I had this week:"}, {"id": "f1", "type": "textarea", "label": "The thinking trap it might be:"}, {"id": "f2", "type": "textarea", "label": "What the trap leaves out:"}, {"id": "f3", "type": "textarea", "label": "A more balanced version:"}, {"id": "f4", "type": "textarea", "label": "How I feel after rewording it:"}]'::jsonb, array['thinking traps', 'cognitive restructuring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('behavioral-activation-pleasure-and-mastery-log', 'Behavioral Activation Pleasure and Mastery Log', 'cbt'::resource_kind, 'A daily log rating activities for enjoyment and sense of accomplishment.', 'Use it to help a client see which activities lift mood or confidence.', array['Adults']::text[], 'One week', 'Ask the client to rate each activity from 0 to 10 on both measures right after doing it, not from memory. Look together for activities that score higher than expected, and plan to add one more of them next week.', '[{"id": "f0", "type": "textarea", "label": "Activity:"}, {"id": "f1", "type": "textarea", "label": "Enjoyment, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "Sense of accomplishment, 0 to 10:"}, {"id": "f3", "type": "textarea", "label": "What I expected beforehand:"}, {"id": "f4", "type": "textarea", "label": "One I want to do again:"}]'::jsonb, array['behavioral activation', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('worry-time-postponement-card', 'Worry Time Postponement Card', 'cbt'::resource_kind, 'A card for noting a worry and holding it for a set worry period later.', 'Use it to help a client practice setting a worry aside until a chosen time.', array['Adults']::text[], 'Two weeks', 'Agree on a fifteen minute worry period at a time that is not near bedtime. During the day the client jots the worry in a few words and returns to the task. Check in on which worries still matter when the time arrives.', '[{"id": "f0", "type": "textarea", "label": "The worry, in a few words:"}, {"id": "f1", "type": "textarea", "label": "What I did instead right then:"}, {"id": "f2", "type": "textarea", "label": "My worry period time:"}, {"id": "f3", "type": "textarea", "label": "Does it still matter now?"}, {"id": "f4", "type": "textarea", "label": "What I can do about it, if anything:"}]'::jsonb, array['worry', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('cost-of-avoiding-ledger', 'Cost of Avoiding Ledger', 'cbt'::resource_kind, 'A ledger of what a client gains and loses each time they avoid something.', 'Use it to help a client see the short and long term cost of avoiding.', array['Adults']::text[], '20 minutes', 'List one avoided situation and fill both sides honestly. Relief in the moment is real and worth naming. Then look at what the avoidance has taken over weeks, and ask whether the client wants to try one small step toward it.', '[{"id": "f0", "type": "textarea", "label": "Something I have been avoiding:"}, {"id": "f1", "type": "textarea", "label": "What I gain right away by avoiding:"}, {"id": "f2", "type": "textarea", "label": "What I lose over time:"}, {"id": "f3", "type": "textarea", "label": "What matters to me that it blocks:"}, {"id": "f4", "type": "textarea", "label": "One small step I could try:"}]'::jsonb, array['avoidance', 'exposure']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('held-thought-hands-experiment-page', 'Held Thought Hands Experiment Page', 'act'::resource_kind, 'A page using hands held up to the face and then lowered to show thoughts as held, not fused.', 'Use it to help a client feel the difference between holding and being stuck to a thought.', array['Adults']::text[], '20 minutes', 'Run the hands exercise in session first: hands over the eyes, then held out in front. Ask what changes about seeing and acting. The page lets the client note thoughts they hold tightly and what they could do with their hands free.', '[{"id": "f0", "type": "textarea", "label": "A thought I hold tightly:"}, {"id": "f1", "type": "textarea", "label": "What it is like with my hands over my eyes:"}, {"id": "f2", "type": "textarea", "label": "What changes when I hold it out in front:"}, {"id": "f3", "type": "textarea", "label": "What I could do with my hands free:"}, {"id": "f4", "type": "textarea", "label": "How I will remember this:"}]'::jsonb, array['defusion', 'core ACT']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('values-interview-with-a-friend-page', 'Values Interview With a Friend Page', 'act'::resource_kind, 'A page for asking a trusted person what they see the client caring about.', 'Use it to help a client check their values against how others see them.', array['Adults']::text[], 'One week', 'The client asks a trusted person two or three questions and records the answers. Compare the replies with the client''s own values list. Notice surprises without judging them, and ask which answers feel true.', '[{"id": "f0", "type": "textarea", "label": "Who I will ask:"}, {"id": "f1", "type": "textarea", "label": "What I asked them:"}, {"id": "f2", "type": "textarea", "label": "What they said I care about:"}, {"id": "f3", "type": "textarea", "label": "What surprised me:"}, {"id": "f4", "type": "textarea", "label": "What I want to keep or change:"}]'::jsonb, array['values', 'connection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('willing-hands-open-practice-log', 'Willing Hands Open Practice Log', 'act'::resource_kind, 'A log of moments a client practiced making room for a hard feeling.', 'Use it to help a client notice willingness as something they choose.', array['Adults']::text[], 'Two weeks', 'Teach the open hands posture as a prompt, not a trick for making a feeling go away. The client records when they used it and what they did next. Expect uneven weeks, and read them for choices rather than results.', '[{"id": "f0", "type": "textarea", "label": "The hard feeling that showed up:"}, {"id": "f1", "type": "textarea", "label": "How I made room for it:"}, {"id": "f2", "type": "textarea", "label": "What I did next:"}, {"id": "f3", "type": "textarea", "label": "What it cost me and what it gave me:"}, {"id": "f4", "type": "textarea", "label": "What I will try next time:"}]'::jsonb, array['willingness', 'acceptance']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('self-as-sky-observer-page', 'Self as Sky Observer Page', 'act'::resource_kind, 'A page using the sky and weather as a picture of the observing self and passing feelings.', 'Use it to help a client step back and watch inner weather without being swept up.', array['Adults']::text[], '20 minutes', 'Guide the client to picture a wide sky with weather moving through it. Have them name the current weather inside them, then notice the part that is watching. Keep it light and let the client use their own images.', '[{"id": "f0", "type": "textarea", "label": "The weather inside me right now:"}, {"id": "f1", "type": "textarea", "label": "What the sky is like around it:"}, {"id": "f2", "type": "textarea", "label": "What it is like to be the one watching:"}, {"id": "f3", "type": "textarea", "label": "A time this view would help:"}, {"id": "f4", "type": "textarea", "label": "One word for the sky part of me:"}]'::jsonb, array['self as context', 'mindfulness']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('five-minute-action-agreement', 'Five Minute Action Agreement', 'act'::resource_kind, 'A short contract naming one small action in service of a value and when it will happen.', 'Use it to help a client turn a value into one action scheduled this week.', array['Adults']::text[], '15 minutes', 'Choose an action small enough that the client is nearly sure to do it. Name the value, the time, and the barrier. Review next session and treat a missed action as a chance to shrink the step, not to push harder.', '[{"id": "f0", "type": "textarea", "label": "The value I am acting on:"}, {"id": "f1", "type": "textarea", "label": "The action, in one sentence:"}, {"id": "f2", "type": "textarea", "label": "When and where I will do it:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way:"}, {"id": "f4", "type": "textarea", "label": "How I will respond if it does:"}]'::jsonb, array['committed action', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('pause-step-back-observe-proceed-card', 'Pause Step Back Observe Proceed Card', 'dbt'::resource_kind, 'A card walking a client through stop, take a step back, observe and proceed mindfully.', 'Use it to help a client pause before acting on a strong urge.', array['Adults']::text[], '15 minutes', 'Practice the steps on a mild situation in session before expecting a client to use them at a high point. Have them write what each step looked like for them. Revisit and shorten the card over weeks.', '[{"id": "f0", "type": "textarea", "label": "The situation that pulled at me:"}, {"id": "f1", "type": "textarea", "label": "What stopping looked like:"}, {"id": "f2", "type": "textarea", "label": "What I noticed when I stepped back:"}, {"id": "f3", "type": "textarea", "label": "What I observed in my body and thoughts:"}, {"id": "f4", "type": "textarea", "label": "How I proceeded:"}]'::jsonb, array['distress tolerance', 'core DBT']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('tipp-temperature-skill-planner', 'TIPP Temperature Skill Planner', 'dbt'::resource_kind, 'A planner for choosing a body-based skill such as cold water or paced breathing ahead of time.', 'Use it to help a client pick a body-based skill for high arousal in advance.', array['Adults']::text[], '20 minutes', 'Check with the client about any health reasons to avoid cold or intense exercise before they practice, and defer to their medical provider. Plan which skill fits which setting, and rehearse once in session.', '[{"id": "f0", "type": "textarea", "label": "When my arousal is highest:"}, {"id": "f1", "type": "textarea", "label": "The body skill I will try first:"}, {"id": "f2", "type": "textarea", "label": "Where I can do it at home or work:"}, {"id": "f3", "type": "textarea", "label": "Any health reason to skip it:"}, {"id": "f4", "type": "textarea", "label": "How I will know it helped enough:"}]'::jsonb, array['distress tolerance', 'TIPP']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-an-urge-grid', 'Pros and Cons of Acting on an Urge Grid', 'dbt'::resource_kind, 'A four-box grid weighing acting on or resisting an urge, short and long term.', 'Use it to help a client slow down and see both sides of an urge.', array['Adults']::text[], '20 minutes', 'Fill all four boxes honestly, including the pull toward the urge. Ask the client to pick the box that surprised them. This works best before a hard moment, so rehearse it ahead rather than at the peak of an urge.', '[{"id": "f0", "type": "textarea", "label": "The urge I am facing:"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it:"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it:"}, {"id": "f3", "type": "textarea", "label": "Pros of resisting it:"}, {"id": "f4", "type": "textarea", "label": "Cons of resisting it:"}]'::jsonb, array['urges', 'distress tolerance']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-turning-the-mind-page', 'Radical Acceptance Turning the Mind Page', 'dbt'::resource_kind, 'A page for noticing non-acceptance and choosing to turn the mind toward what is.', 'Use it to help a client practice accepting a fact they cannot change.', array['Adults']::text[], '25 minutes', 'Explain that acceptance does not mean approval. The client names a fact, notices how they fight it, and picks a body and action cue for turning the mind. Expect to repeat this, since it is a choice made again and again.', '[{"id": "f0", "type": "textarea", "label": "The fact I am fighting:"}, {"id": "f1", "type": "textarea", "label": "How the fighting shows up:"}, {"id": "f2", "type": "textarea", "label": "What accepting it would not mean:"}, {"id": "f3", "type": "textarea", "label": "How I will turn my mind:"}, {"id": "f4", "type": "textarea", "label": "One thing I can still choose:"}]'::jsonb, array['acceptance', 'core DBT']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('self-respect-request-rehearsal-page', 'Self-Respect Request Rehearsal Page', 'dbt'::resource_kind, 'A sheet for rehearsing fair, apologies-free, stick-to-values and truthful requests.', 'Use it to help a client keep their self-respect while asking for something.', array['Adults']::text[], '25 minutes', 'Walk through fair, apologies, stick to values and truthful using a real upcoming request. Role play it once and talk about which part is hardest. Let the client choose the words, so the script stays believable.', '[{"id": "f0", "type": "textarea", "label": "What I want to ask for:"}, {"id": "f1", "type": "textarea", "label": "How I can be fair to both of us:"}, {"id": "f2", "type": "textarea", "label": "The apology I do not need to make:"}, {"id": "f3", "type": "textarea", "label": "The value I want to stick to:"}, {"id": "f4", "type": "textarea", "label": "My honest request in a few words:"}]'::jsonb, array['interpersonal effectiveness', 'FAST']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('weekly-state-of-us-check-in-sheet', 'Weekly State of Us Check-In Sheet', 'couples'::resource_kind, 'A shared sheet for a weekly talk about what is going well and what needs attention.', 'Use it to give partners a steady time to raise issues before they build.', array['Couples']::text[], '30 minutes weekly', 'Each partner fills their side privately, then they swap and take turns reading. Set a rule that the listener repeats back before replying. Keep it short and end on one thing each partner appreciated.', '[{"id": "f0", "type": "textarea", "label": "One thing that went well between us:"}, {"id": "f1", "type": "textarea", "label": "One thing I appreciated about you:"}, {"id": "f2", "type": "textarea", "label": "One thing I need this week:"}, {"id": "f3", "type": "textarea", "label": "A worry I want to name calmly:"}, {"id": "f4", "type": "textarea", "label": "One thing we will do together:"}]'::jsonb, array['communication', 'check-in']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('stress-reducing-conversation-turns-page', 'Stress Reducing Conversation Turns Page', 'couples'::resource_kind, 'A turn-taking page where one partner shares an outside stress while the other listens.', 'Use it to help partners support each other about stress outside the relationship.', array['Couples']::text[], '30 minutes', 'Each partner gets a turn to speak about a stress that is not about the other, while the listener asks open questions and does not fix. Coach them to show understanding first and offer advice only if asked.', '[{"id": "f0", "type": "textarea", "label": "The stress I want to talk about:"}, {"id": "f1", "type": "textarea", "label": "What I need from you while I talk:"}, {"id": "f2", "type": "textarea", "label": "What I heard my partner say:"}, {"id": "f3", "type": "textarea", "label": "How I showed I understood:"}, {"id": "f4", "type": "textarea", "label": "What I will do to support you this week:"}]'::jsonb, array['support', 'Gottman']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('fair-share-of-home-tasks-sorting-sheet', 'Fair Share of Home Tasks Sorting Sheet', 'couples'::resource_kind, 'A card sort for dividing household tasks in a way both partners agree is fair.', 'Use it to help partners talk about household load without scorekeeping.', array['Couples']::text[], '40 minutes', 'List every task on cards, including planning and remembering, then sort them together. Notice which tasks are invisible. Aim for a trial split for one week rather than a final answer, and revisit it.', '[{"id": "f0", "type": "textarea", "label": "Tasks I do now:"}, {"id": "f1", "type": "textarea", "label": "Tasks I wish were shared:"}, {"id": "f2", "type": "textarea", "label": "Tasks I would trade:"}, {"id": "f3", "type": "textarea", "label": "What feels fair to me and why:"}, {"id": "f4", "type": "textarea", "label": "Our trial split for this week:"}]'::jsonb, array['planning', 'negotiation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('small-rituals-choosing-menu-for-two', 'Small Rituals Choosing Menu for Two', 'couples'::resource_kind, 'A menu of small daily and weekly rituals for partners to choose from.', 'Use it to help partners pick a few rituals that fit their life.', array['Couples']::text[], '30 minutes', 'Have each partner mark ideas they like and then compare. Choose one daily and one weekly ritual that both can keep, however small. Return to it after two weeks and adjust without blame if it faded.', '[{"id": "f0", "type": "textarea", "label": "A daily ritual I would enjoy:"}, {"id": "f1", "type": "textarea", "label": "A weekly ritual I would enjoy:"}, {"id": "f2", "type": "textarea", "label": "What would make it easy to keep:"}, {"id": "f3", "type": "textarea", "label": "What might get in the way:"}, {"id": "f4", "type": "textarea", "label": "The one we will start with:"}]'::jsonb, array['rituals', 'connection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('hard-topic-pause-and-return-plan', 'Hard Topic Pause and Return Plan', 'couples'::resource_kind, 'A shared plan for pausing a heated talk and returning to it later.', 'Use it to help partners take a break and come back instead of leaving it open.', array['Couples']::text[], '25 minutes', 'Agree on a signal, a length of break, and a time to return, written together while calm. Practice the signal in session. The partner who calls the pause is the one who starts the return conversation.', '[{"id": "f0", "type": "textarea", "label": "Our signal for pausing:"}, {"id": "f1", "type": "textarea", "label": "How long we will take:"}, {"id": "f2", "type": "textarea", "label": "What I will do during the break:"}, {"id": "f3", "type": "textarea", "label": "The time we will come back:"}, {"id": "f4", "type": "textarea", "label": "The first sentence I will use when we return:"}]'::jsonb, array['conflict', 'repair']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('feelings-forecast-station-craft', 'Feelings Forecast Station Craft', 'kids'::resource_kind, 'A craft where a child builds a weather dial to show how they feel today.', 'Use it to help a child show feelings without needing the words.', array['Children']::text[], '30 minutes', 'The child decorates a paper plate dial with weather for each feeling. The parent joins by showing their own weather for the day. Use it as a daily check-in at a set time and accept any weather the child chooses.', '[{"id": "f0", "type": "textarea", "label": "Draw the weather for a happy day:"}, {"id": "f1", "type": "textarea", "label": "Draw the weather for a mad day:"}, {"id": "f2", "type": "textarea", "label": "Draw the weather for a worried day:"}, {"id": "f3", "type": "textarea", "label": "Today my weather is:"}, {"id": "f4", "type": "textarea", "label": "Who I will show my dial to:"}]'::jsonb, array['feelings', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('calm-down-jar-making-page', 'Calm Down Jar Making Page', 'kids'::resource_kind, 'A page for building a glitter jar and drawing what the child does while it settles.', 'Use it to help a child practice slowing down while watching the glitter fall.', array['Children']::text[], '30 minutes', 'Make the jar together with the child and parent. Shake it, then breathe while the glitter settles. The parent keeps the jar available and offers it without making it a punishment. Let the child choose the colors.', '[{"id": "f0", "type": "textarea", "label": "Draw my jar:"}, {"id": "f1", "type": "textarea", "label": "What I feel when I shake it:"}, {"id": "f2", "type": "textarea", "label": "What I do while the glitter falls:"}, {"id": "f3", "type": "textarea", "label": "How I feel when it is still:"}, {"id": "f4", "type": "textarea", "label": "Where I will keep my jar:"}]'::jsonb, array['calming', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('courage-medal-design-page', 'Courage Medal Design Page', 'kids'::resource_kind, 'A page for designing a medal for a time the child did something brave.', 'Use it to help a child notice and name their own bravery.', array['Children']::text[], '25 minutes', 'Invite the child to remember a time they felt nervous and did it anyway, and design a medal for it. The parent can add one thing they saw. Keep it focused on effort, not on winning.', '[{"id": "f0", "type": "textarea", "label": "Draw my courage medal:"}, {"id": "f1", "type": "textarea", "label": "What brave thing I did:"}, {"id": "f2", "type": "textarea", "label": "How my body felt:"}, {"id": "f3", "type": "textarea", "label": "Who saw me do it:"}, {"id": "f4", "type": "textarea", "label": "A brave thing I might try next:"}]'::jsonb, array['bravery', 'drawing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('helping-hands-family-tree-drawing', 'Helping Hands Family Tree Drawing', 'kids'::resource_kind, 'A drawing where a child traces hands and writes who helps them.', 'Use it to help a child map the grown-ups and friends they can ask for help.', array['Children']::text[], '30 minutes', 'The child traces a hand for each helper and names what that person helps with. If a child names an unsafe person or tells you something worrying, remember your reporting duties. The parent is invited to add their hand.', '[{"id": "f0", "type": "textarea", "label": "Trace my hand and write a helper on each finger:"}, {"id": "f1", "type": "textarea", "label": "Who helps me when I am sad:"}, {"id": "f2", "type": "textarea", "label": "Who helps me when I am scared:"}, {"id": "f3", "type": "textarea", "label": "How I can ask for help:"}, {"id": "f4", "type": "textarea", "label": "A new helper I could add:"}]'::jsonb, array['support', 'safety']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('mood-music-playlist-making-page', 'Mood Music Playlist Making Page', 'kids'::resource_kind, 'A page for picking songs that match different feelings and drawing how each one feels.', 'Use it to help a child use music to notice and shift feelings.', array['Children']::text[], '30 minutes', 'Have the child pick or hum songs for happy, sad, mad and calm. Listen to a few together. The parent notes one song to use at a tough time. Keep volume comfortable and follow the child''s lead.', '[{"id": "f0", "type": "textarea", "label": "A song for when I am happy:"}, {"id": "f1", "type": "textarea", "label": "A song for when I am sad:"}, {"id": "f2", "type": "textarea", "label": "A song for when I am mad:"}, {"id": "f3", "type": "textarea", "label": "A song that helps me calm down:"}, {"id": "f4", "type": "textarea", "label": "How the music feels in my body:"}]'::jsonb, array['feelings', 'play']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('emotion-charades-spin-wheel-game', 'Emotion Charades Spin Wheel Game', 'game'::resource_kind, 'A group game of acting out feelings from a spin wheel while others guess.', 'Use it to help a group practice reading and naming feelings together.', array['Groups']::text[], '25 minutes', 'Players take turns spinning and acting, with no words. After each guess, ask what clues helped. Debrief by asking when a feeling is hard to read in real life. Skip a turn gracefully for anyone who prefers not to act.', '[{"id": "f0", "type": "textarea", "label": "The feeling I acted out:"}, {"id": "f1", "type": "textarea", "label": "What clues helped people guess:"}, {"id": "f2", "type": "textarea", "label": "A feeling that was hard to show:"}, {"id": "f3", "type": "textarea", "label": "A time I misread someone''s feeling:"}, {"id": "f4", "type": "textarea", "label": "What I learned about reading others:"}]'::jsonb, array['feelings', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('coping-tool-auction-game', 'Coping Tool Auction Game', 'game'::resource_kind, 'A game where players bid play money on coping tools and explain their picks.', 'Use it to help a group compare coping tools and say why they choose them.', array['Groups']::text[], '30 minutes', 'Give each player equal play money and list coping tools to bid on. Winners explain how they would use the tool. Debrief on which tools were popular, which were surprising, and what each person will try this week.', '[{"id": "f0", "type": "textarea", "label": "The tool I bid most on:"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me:"}, {"id": "f2", "type": "textarea", "label": "A tool I did not expect to want:"}, {"id": "f3", "type": "textarea", "label": "When I will use mine:"}, {"id": "f4", "type": "textarea", "label": "What I heard from others:"}]'::jsonb, array['coping skills', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('values-scavenger-hunt-game', 'Values Scavenger Hunt Game', 'game'::resource_kind, 'A game of finding objects in the room that stand for personal values.', 'Use it to help a group connect everyday objects with what they care about.', array['Groups']::text[], '30 minutes', 'Set a few minutes for players to find objects that stand for a value. Take turns sharing, with no one required to speak. Debrief by asking where each value shows up in the week ahead.', '[{"id": "f0", "type": "textarea", "label": "The object I chose:"}, {"id": "f1", "type": "textarea", "label": "The value it stands for:"}, {"id": "f2", "type": "textarea", "label": "A time I lived that value:"}, {"id": "f3", "type": "textarea", "label": "A way I can live it this week:"}, {"id": "f4", "type": "textarea", "label": "A value I heard from someone else:"}]'::jsonb, array['values', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('thought-bubble-pass-along-game', 'Thought Bubble Pass Along Game', 'game'::resource_kind, 'A group game where each player rewrites a passed-along unhelpful thought in a kinder way.', 'Use it to help a group practice reframing thoughts together.', array['Groups']::text[], '25 minutes', 'Each player writes an unhelpful thought on a slip, passes it left, and the next player writes a more balanced version. Keep thoughts general, not private. Debrief on which rewrites felt believable and why.', '[{"id": "f0", "type": "textarea", "label": "The thought I wrote:"}, {"id": "f1", "type": "textarea", "label": "The rewrite I received:"}, {"id": "f2", "type": "textarea", "label": "What made a rewrite believable:"}, {"id": "f3", "type": "textarea", "label": "A rewrite I would use myself:"}, {"id": "f4", "type": "textarea", "label": "How it felt to help someone else:"}]'::jsonb, array['cognitive restructuring', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('calm-corner-relay-game', 'Calm Corner Relay Game', 'game'::resource_kind, 'A relay where teams complete calming tasks in turn, such as breathing and stretching.', 'Use it to help a group rehearse calming skills in a playful way.', array['Groups']::text[], '20 minutes', 'Set up stations for breathing, stretching, naming five things, and a gentle hand squeeze. Teams rotate with no racing against anyone''s body. Debrief on which station helped most and where it can be used in daily life.', '[{"id": "f0", "type": "textarea", "label": "The station I liked best:"}, {"id": "f1", "type": "textarea", "label": "How my body felt afterward:"}, {"id": "f2", "type": "textarea", "label": "When I could use it in real life:"}, {"id": "f3", "type": "textarea", "label": "A station I would add:"}, {"id": "f4", "type": "textarea", "label": "What I will try this week:"}]'::jsonb, array['calming', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('steady-place-senses-builder', 'Steady Place Senses Builder', 'worksheet'::resource_kind, 'A page for building a calm place from the senses, kept free of any story of what happened.', 'Use it to help a client build a steady inner place for grounding.', array['Adults']::text[], '20 minutes', 'Keep the focus on the present senses of a safe place, not on past events. If the client drifts toward memories, gently return to the room. Practice together and let the client choose when to use it.', '[{"id": "f0", "type": "textarea", "label": "Where my safe place is:"}, {"id": "f1", "type": "textarea", "label": "What I see there:"}, {"id": "f2", "type": "textarea", "label": "What I hear and smell there:"}, {"id": "f3", "type": "textarea", "label": "How my body feels there:"}, {"id": "f4", "type": "textarea", "label": "When I could picture it:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'safety']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('safety-versus-danger-present-check-page', 'Safety Versus Danger Present Check Page', 'cbt'::resource_kind, 'A page for checking whether current cues point to present safety or danger.', 'Use it to help a client sort what is happening now from what feels familiar.', array['Adults']::text[], '25 minutes', 'Use a recent reminder that stirred strong reactions. The client lists what is true right now and what feels like the past, without describing the past. Pace the work and stop if the client feels flooded.', '[{"id": "f0", "type": "textarea", "label": "The reminder that stirred me up:"}, {"id": "f1", "type": "textarea", "label": "What is true in the room right now:"}, {"id": "f2", "type": "textarea", "label": "What my body is telling me:"}, {"id": "f3", "type": "textarea", "label": "What I know about today:"}, {"id": "f4", "type": "textarea", "label": "What helps me stay in today:"}]'::jsonb, array['PTSD and trauma', 'thinking traps', 'pacing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('carrying-both-page-for-hard-memories-and-values', 'Carrying Both Page for Hard Memories and Values', 'act'::resource_kind, 'A page for noting that painful reminders and what matters can be present together.', 'Use it to help a client act on values while reminders are around.', array['Adults']::text[], '25 minutes', 'Do not ask for details of past events. The client names how reminders show up in the present and one value-guided step anyway. Keep the pace slow and offer breaks.', '[{"id": "f0", "type": "textarea", "label": "A reminder that shows up:"}, {"id": "f1", "type": "textarea", "label": "What it pulls me away from:"}, {"id": "f2", "type": "textarea", "label": "A value I still want to live:"}, {"id": "f3", "type": "textarea", "label": "One small step I can take today:"}, {"id": "f4", "type": "textarea", "label": "Who can support me:"}]'::jsonb, array['PTSD and trauma', 'values', 'pacing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('arousal-range-check-in-card', 'Arousal Range Check-In Card', 'dbt'::resource_kind, 'A card for noting whether a client feels too high, too low or within range, and a skill for each.', 'Use it to help a client notice arousal level and pick a matching skill.', array['Adults']::text[], '20 minutes', 'Introduce the idea of a range where thinking and feeling stay workable. The client rates now and chooses a skill. If the client mentions risk of harming themselves, complete the safety plan in session, and 988 (call or text) is a support.', '[{"id": "f0", "type": "textarea", "label": "My level right now: too high, too low, or in range:"}, {"id": "f1", "type": "textarea", "label": "What I notice in my body:"}, {"id": "f2", "type": "textarea", "label": "A skill I will try:"}, {"id": "f3", "type": "textarea", "label": "What I will do if it is not enough:"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) is available if I feel unsafe:"}]'::jsonb, array['PTSD and trauma', 'window of tolerance', 'grounding']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('orienting-around-the-room-game', 'Orienting Around the Room Game', 'game'::resource_kind, 'A game where players take turns noticing and naming things in the room that are safe.', 'Use it to help a group practice orienting to the present together.', array['Groups']::text[], '15 minutes', 'Players take turns naming a color, a shape, or a sound in the room, with no one asked to share anything personal. Debrief on how it felt in the body. Let anyone sit out and watch.', '[{"id": "f0", "type": "textarea", "label": "Something I noticed:"}, {"id": "f1", "type": "textarea", "label": "What changed in my body:"}, {"id": "f2", "type": "textarea", "label": "A place I could do this outside:"}, {"id": "f3", "type": "textarea", "label": "What was hard about it:"}, {"id": "f4", "type": "textarea", "label": "Who I might do it with:"}]'::jsonb, array['PTSD and trauma', 'grounding', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('worry-hour-appointment-book', 'Worry Hour Appointment Book', 'worksheet'::resource_kind, 'A page for scheduling a daily worry appointment and noting what came up.', 'Use it to help a client contain worry in a set slot.', array['Adults']::text[], 'Two weeks', 'Choose a time that is not near sleep. Between appointments the client writes a note and returns to what they were doing. At the appointment, sort worries into those with a step and those without.', '[{"id": "f0", "type": "textarea", "label": "Worry noted:"}, {"id": "f1", "type": "textarea", "label": "What I did instead:"}, {"id": "f2", "type": "textarea", "label": "At my appointment, a step I can take:"}, {"id": "f3", "type": "textarea", "label": "A worry I can let sit:"}, {"id": "f4", "type": "textarea", "label": "How the day felt:"}]'::jsonb, array['anxiety', 'worry', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('likelihood-and-coping-estimate-page', 'Likelihood and Coping Estimate Page', 'cbt'::resource_kind, 'A page for rating how likely a feared outcome is and how well the client could cope.', 'Use it to help a client weigh both the odds and their own coping.', array['Adults']::text[], '25 minutes', 'Ask for a number for likelihood and a number for coping, then list what the client would do if it happened. Many people find the second number higher than they guessed. Hold the numbers lightly.', '[{"id": "f0", "type": "textarea", "label": "The outcome I fear:"}, {"id": "f1", "type": "textarea", "label": "Likelihood, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "What I would do if it happened:"}, {"id": "f3", "type": "textarea", "label": "Coping, 0 to 100:"}, {"id": "f4", "type": "textarea", "label": "Who could help me:"}]'::jsonb, array['anxiety', 'predictions', 'worry']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('anxiety-passenger-seat-page', 'Anxiety Passenger Seat Page', 'act'::resource_kind, 'A page for letting anxiety ride along while the client drives toward a value.', 'Use it to help a client act on values with anxiety present.', array['Adults']::text[], '25 minutes', 'Use the picture of anxiety in the passenger seat. The client names where they want to go and what anxiety says. Practice one step with anxiety along for the ride and review how it went.', '[{"id": "f0", "type": "textarea", "label": "Where I want to drive:"}, {"id": "f1", "type": "textarea", "label": "What anxiety says from the passenger seat:"}, {"id": "f2", "type": "textarea", "label": "What I do with my hands on the wheel:"}, {"id": "f3", "type": "textarea", "label": "One step I will take this week:"}, {"id": "f4", "type": "textarea", "label": "What I will say to anxiety:"}]'::jsonb, array['anxiety', 'values', 'defusion']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('self-soothe-by-senses-anxiety-card', 'Self-Soothe by Senses Anxiety Card', 'dbt'::resource_kind, 'A card matching each sense with a soothing action for anxious moments.', 'Use it to help a client choose a soothing step for each sense.', array['Adults']::text[], '20 minutes', 'Fill one idea per sense with the client and test one in session. Pick two they would use in real life. Revisit the card when something no longer works.', '[{"id": "f0", "type": "textarea", "label": "Something soothing to see:"}, {"id": "f1", "type": "textarea", "label": "Something soothing to hear:"}, {"id": "f2", "type": "textarea", "label": "Something soothing to smell:"}, {"id": "f3", "type": "textarea", "label": "Something soothing to taste or touch:"}, {"id": "f4", "type": "textarea", "label": "The two I will keep handy:"}]'::jsonb, array['anxiety', 'self-soothing', 'distress tolerance']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('worry-muncher-box-craft', 'Worry Muncher Box Craft', 'kids'::resource_kind, 'A craft box monster a child feeds with written or drawn worries.', 'Use it to help a child put worries outside themselves and share them.', array['Children']::text[], '30 minutes', 'The child decorates a box with a mouth and drops worry notes in. The parent reads the notes at a set time and asks what help is wanted. Keep the tone friendly and avoid dismissing any worry.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry monster:"}, {"id": "f1", "type": "textarea", "label": "A worry I will feed it today:"}, {"id": "f2", "type": "textarea", "label": "What it looks like when I am worried:"}, {"id": "f3", "type": "textarea", "label": "Who I will tell:"}, {"id": "f4", "type": "textarea", "label": "What helps me feel better:"}]'::jsonb, array['anxiety', 'worry', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('low-mood-day-minimum-plan', 'Low Mood Day Minimum Plan', 'worksheet'::resource_kind, 'A page naming the smallest set of actions for a hard day.', 'Use it to help a client keep a floor of care on low days.', array['Adults']::text[], '20 minutes', 'Build the plan on a better day. The minimum might be a meal, light, one message and a short walk. If the client mentions thoughts of ending their life, make a safety plan in session; 988 (call or text) is available. Do not hand this out as sole support.', '[{"id": "f0", "type": "textarea", "label": "My minimum for a hard day:"}, {"id": "f1", "type": "textarea", "label": "Who I can message:"}, {"id": "f2", "type": "textarea", "label": "What I can do for my body:"}, {"id": "f3", "type": "textarea", "label": "What I will skip without guilt:"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) is there if I feel unsafe:"}]'::jsonb, array['depression', 'behavioral activation', 'safety']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('all-or-nothing-day-review-page', 'All or Nothing Day Review Page', 'cbt'::resource_kind, 'A page for reviewing a day that felt like a total failure and finding what was in between.', 'Use it to help a client see partial wins in a day judged as all bad.', array['Adults']::text[], '25 minutes', 'Ask the client to rate the day, then list what was done even in a small way. Compare the first rating with the second. Avoid pushing a cheerful view and let small changes stand.', '[{"id": "f0", "type": "textarea", "label": "How I rated the day:"}, {"id": "f1", "type": "textarea", "label": "What I did, even small:"}, {"id": "f2", "type": "textarea", "label": "What was outside my control:"}, {"id": "f3", "type": "textarea", "label": "A fairer rating:"}, {"id": "f4", "type": "textarea", "label": "What I could do tomorrow:"}]'::jsonb, array['depression', 'thinking traps', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('values-in-slow-motion-page', 'Values in Slow Motion Page', 'act'::resource_kind, 'A page for choosing a very small way to live a value when energy is low.', 'Use it to help a client act on a value in a tiny way.', array['Adults']::text[], '20 minutes', 'Choose one value and shrink the action until it takes five minutes or less. Link it to a time and a cue. Celebrate doing the step and not the mood afterward.', '[{"id": "f0", "type": "textarea", "label": "A value that matters:"}, {"id": "f1", "type": "textarea", "label": "The smallest version of it:"}, {"id": "f2", "type": "textarea", "label": "When I will do it:"}, {"id": "f3", "type": "textarea", "label": "What may get in the way:"}, {"id": "f4", "type": "textarea", "label": "What I notice after doing it:"}]'::jsonb, array['depression', 'values', 'committed action']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('mood-lift-opposite-action-plan', 'Mood Lift Opposite Action Plan', 'dbt'::resource_kind, 'A plan for choosing an action opposite to withdrawing when mood is low.', 'Use it to help a client try the opposite of an urge to pull away.', array['Adults']::text[], '25 minutes', 'Name the urge, then choose an action that points the other way, kept small. Check that the action fits the situation first. Review how mood moved, not whether the action felt good.', '[{"id": "f0", "type": "textarea", "label": "The urge I notice:"}, {"id": "f1", "type": "textarea", "label": "The opposite action I will try:"}, {"id": "f2", "type": "textarea", "label": "When I will do it:"}, {"id": "f3", "type": "textarea", "label": "What I notice after:"}, {"id": "f4", "type": "textarea", "label": "What I will do next time:"}]'::jsonb, array['depression', 'opposite action', 'emotion regulation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('mood-garden-weather-journal-craft', 'Mood Garden Weather Journal Craft', 'kids'::resource_kind, 'A craft journal where a child draws a garden that changes with their mood.', 'Use it to help a child notice and show shifts in mood over days.', array['Children']::text[], '30 minutes', 'The child draws a garden each day with weather matching their mood. The parent looks at it with them without fixing. Share patterns with the clinician and remember reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my garden today:"}, {"id": "f1", "type": "textarea", "label": "The weather in my garden:"}, {"id": "f2", "type": "textarea", "label": "What helped my garden:"}, {"id": "f3", "type": "textarea", "label": "What I want my garden to have:"}, {"id": "f4", "type": "textarea", "label": "Who I will show it to:"}]'::jsonb, array['depression', 'mood', 'drawing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('first-two-minutes-launch-sheet', 'First Two Minutes Launch Sheet', 'worksheet'::resource_kind, 'A sheet for naming the first two minutes of a task and what to have ready.', 'Use it to help a client get over the hump of starting.', array['Adults']::text[], '20 minutes', 'Choose a task the client keeps putting off and break out only the first physical action. Place cues and tools where they will be needed. Review next week and adjust for what actually helped.', '[{"id": "f0", "type": "textarea", "label": "The task I keep putting off:"}, {"id": "f1", "type": "textarea", "label": "The first two minute action:"}, {"id": "f2", "type": "textarea", "label": "What I need within reach:"}, {"id": "f3", "type": "textarea", "label": "Where I will put the cue:"}, {"id": "f4", "type": "textarea", "label": "How I will reward starting:"}]'::jsonb, array['ADHD', 'routines', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('distraction-log-and-re-entry-cue-page', 'Distraction Log and Re-Entry Cue Page', 'cbt'::resource_kind, 'A log of distractions and a cue for coming back to the task.', 'Use it to help a client notice distractions and plan a way back.', array['Adults']::text[], 'One week', 'Ask the client to note each pull away in a few words, without judging, then plan one phrase or action that brings them back. Look together at which distractions repeat.', '[{"id": "f0", "type": "textarea", "label": "What I was working on:"}, {"id": "f1", "type": "textarea", "label": "What pulled me away:"}, {"id": "f2", "type": "textarea", "label": "How long I was away:"}, {"id": "f3", "type": "textarea", "label": "My cue to return:"}, {"id": "f4", "type": "textarea", "label": "A change I could make:"}]'::jsonb, array['ADHD', 'self-monitoring', 'focus']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('interest-versus-importance-values-page', 'Interest Versus Importance Values Page', 'act'::resource_kind, 'A page sorting tasks by what interests the client and what matters to them.', 'Use it to help a client link boring but important tasks to values.', array['Adults']::text[], '25 minutes', 'Sort tasks into interesting and important, then connect the boring but important ones with a value. Pair them with something enjoyable. Keep the sorting practical.', '[{"id": "f0", "type": "textarea", "label": "A boring task that matters:"}, {"id": "f1", "type": "textarea", "label": "The value behind it:"}, {"id": "f2", "type": "textarea", "label": "Something I can pair with it:"}, {"id": "f3", "type": "textarea", "label": "How long I can do it:"}, {"id": "f4", "type": "textarea", "label": "How I will know I did it:"}]'::jsonb, array['ADHD', 'values', 'committed action']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('emotional-spike-pause-plan', 'Emotional Spike Pause Plan', 'dbt'::resource_kind, 'A plan for pausing when frustration spikes during tasks.', 'Use it to help a client slow down in the moment of a fast emotional reaction.', array['Adults']::text[], '20 minutes', 'Name the early signs, pick a short pause, and plan what to say. Practice once. A client with a fast reaction may need cues in the environment more than willpower.', '[{"id": "f0", "type": "textarea", "label": "How I know a spike is coming:"}, {"id": "f1", "type": "textarea", "label": "My pause action:"}, {"id": "f2", "type": "textarea", "label": "What I will say:"}, {"id": "f3", "type": "textarea", "label": "What I will do next:"}, {"id": "f4", "type": "textarea", "label": "What helped before:"}]'::jsonb, array['ADHD', 'impulsivity', 'emotion regulation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('beat-the-clock-chore-relay-game', 'Beat the Clock Chore Relay Game', 'game'::resource_kind, 'A game where family members race gently against a timer to finish a short chore.', 'Use it to help a family make short tasks playful.', array['Groups']::text[], '20 minutes', 'Set a timer for a small task, with turns and a rule that quality counts too. Debrief on what made the task easier. Avoid shaming anyone for being slower.', '[{"id": "f0", "type": "textarea", "label": "The task we raced:"}, {"id": "f1", "type": "textarea", "label": "What helped me start:"}, {"id": "f2", "type": "textarea", "label": "What made it harder:"}, {"id": "f3", "type": "textarea", "label": "A reward we agreed on:"}, {"id": "f4", "type": "textarea", "label": "How I would change the game:"}]'::jsonb, array['ADHD', 'focus', 'family']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('urge-surfing-journal-page', 'Urge Surfing Journal Page', 'worksheet'::resource_kind, 'A page for noting an urge, its peak and how it passed.', 'Use it to help a client see that an urge rises and falls.', array['Adults']::text[], 'One week', 'Teach the client to watch the urge like a wave and rate it at intervals. Keep the language on substance use and urges. Look at the log together and note what helped it pass.', '[{"id": "f0", "type": "textarea", "label": "The urge, in a few words:"}, {"id": "f1", "type": "textarea", "label": "Rating at the start, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "What I did while it peaked:"}, {"id": "f3", "type": "textarea", "label": "Rating when it passed:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['addiction', 'urges', 'mindfulness']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('high-risk-situation-planning-page', 'High Risk Situation Planning Page', 'cbt'::resource_kind, 'A page for naming situations that raise the chance of substance use and a plan for each.', 'Use it to help a client plan ahead for hard situations.', array['Adults']::text[], '30 minutes', 'List people, places and times, then plan an exit and a call. Role play one. Review what worked next session, and keep the tone free of blame.', '[{"id": "f0", "type": "textarea", "label": "A situation that raises my risk:"}, {"id": "f1", "type": "textarea", "label": "The first warning sign:"}, {"id": "f2", "type": "textarea", "label": "What I will do:"}, {"id": "f3", "type": "textarea", "label": "Who I will call:"}, {"id": "f4", "type": "textarea", "label": "What I will tell myself:"}]'::jsonb, array['addiction', 'triggers', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('reasons-and-values-compass-page', 'Reasons and Values Compass Page', 'act'::resource_kind, 'A page tying the client''s reasons for change to values.', 'Use it to help a client link change to what matters most.', array['Adults']::text[], '25 minutes', 'Ask what the client wants their life to be about, and connect each reason to a value. Keep it in their words. Return to the page when motivation dips.', '[{"id": "f0", "type": "textarea", "label": "Why I want to change:"}, {"id": "f1", "type": "textarea", "label": "What matters most to me:"}, {"id": "f2", "type": "textarea", "label": "A step toward it this week:"}, {"id": "f3", "type": "textarea", "label": "What gets in the way:"}, {"id": "f4", "type": "textarea", "label": "Who supports me:"}]'::jsonb, array['addiction', 'values', 'motivation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('crisis-survival-skills-card-for-urges', 'Crisis Survival Skills Card for Urges', 'dbt'::resource_kind, 'A card of distress skills for getting through an urge without using.', 'Use it to help a client have a short list ready for strong urges.', array['Adults']::text[], '20 minutes', 'Build the list together, including distraction, cold water and calling someone. Practice one in session. If the client mentions thoughts of self-harm, make a plan in session; 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "My top three skills for an urge:"}, {"id": "f1", "type": "textarea", "label": "A person I can call:"}, {"id": "f2", "type": "textarea", "label": "A place I can go:"}, {"id": "f3", "type": "textarea", "label": "What I will say to myself:"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) if I feel unsafe:"}]'::jsonb, array['addiction', 'distress tolerance', 'urges']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('supporting-recovery-together-talk-sheet', 'Supporting Recovery Together Talk Sheet', 'couples'::resource_kind, 'A sheet for partners to talk about how the partner can support without taking over.', 'Use it to help partners agree on supportive roles.', array['Couples']::text[], '40 minutes', 'Each partner names what helps and what does not. Keep the language on substance use and urges. Agree on one supportive action and one boundary, and check on how it works next session.', '[{"id": "f0", "type": "textarea", "label": "What helps me when I have urges:"}, {"id": "f1", "type": "textarea", "label": "What does not help:"}, {"id": "f2", "type": "textarea", "label": "One thing my partner can do:"}, {"id": "f3", "type": "textarea", "label": "One boundary I need:"}, {"id": "f4", "type": "textarea", "label": "How we will check in:"}]'::jsonb, array['addiction', 'support', 'boundaries']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('anger-ladder-intensity-page', 'Anger Ladder Intensity Page', 'worksheet'::resource_kind, 'A ladder for rating anger from irritated to furious with body signs at each rung.', 'Use it to help a client notice anger early.', array['Adults']::text[], '20 minutes', 'Place a recent event on the ladder and add body signs at each step. Pick a step at which to use a skill. Return to the ladder to see if the client catches it sooner.', '[{"id": "f0", "type": "textarea", "label": "Rung one: what I notice:"}, {"id": "f1", "type": "textarea", "label": "A middle rung: what I notice:"}, {"id": "f2", "type": "textarea", "label": "The top rung: what I notice:"}, {"id": "f3", "type": "textarea", "label": "The rung I want to act at:"}, {"id": "f4", "type": "textarea", "label": "What I will do there:"}]'::jsonb, array['anger management', 'body signals', 'regulation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('anger-should-statements-rewrite-page', 'Anger Should Statements Rewrite Page', 'cbt'::resource_kind, 'A page for rewriting should and must statements about others.', 'Use it to help a client loosen rigid rules that fuel anger.', array['Adults']::text[], '25 minutes', 'Find the demands in the client''s anger, then reword them as preferences. Ask what changes in the body. Keep it from sounding like the other person was right.', '[{"id": "f0", "type": "textarea", "label": "The should I notice:"}, {"id": "f1", "type": "textarea", "label": "How it feels in my body:"}, {"id": "f2", "type": "textarea", "label": "A preference version:"}, {"id": "f3", "type": "textarea", "label": "What I can control:"}, {"id": "f4", "type": "textarea", "label": "What I will do:"}]'::jsonb, array['anger management', 'thinking traps', 'thought record']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('anger-underneath-page', 'Anger Underneath Page', 'act'::resource_kind, 'A page for finding what feelings and values sit under anger.', 'Use it to help a client see hurt or fear under anger.', array['Adults']::text[], '25 minutes', 'Ask what the anger is protecting. Name softer feelings, and what the client cares about. Let the client decide how much to share with others.', '[{"id": "f0", "type": "textarea", "label": "What made me angry:"}, {"id": "f1", "type": "textarea", "label": "What I felt underneath:"}, {"id": "f2", "type": "textarea", "label": "What I care about here:"}, {"id": "f3", "type": "textarea", "label": "A useful action:"}, {"id": "f4", "type": "textarea", "label": "What I will leave alone:"}]'::jsonb, array['anger management', 'values', 'emotion identification']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('cooling-off-and-coming-back-agreement', 'Cooling Off and Coming Back Agreement', 'couples'::resource_kind, 'An agreement for pausing when anger rises and returning to the talk.', 'Use it to help partners cool off and reconnect.', array['Couples']::text[], '30 minutes', 'Fill it out together when calm. Include a signal, a break time and who restarts. Practice the signal in session. If anyone feels unsafe, the plan is to separate and seek support.', '[{"id": "f0", "type": "textarea", "label": "Our pause signal:"}, {"id": "f1", "type": "textarea", "label": "How long we take:"}, {"id": "f2", "type": "textarea", "label": "What I do to cool down:"}, {"id": "f3", "type": "textarea", "label": "Who restarts the talk:"}, {"id": "f4", "type": "textarea", "label": "Our first words when back:"}]'::jsonb, array['anger management', 'conflict', 'time-out']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('heat-gauge-anger-craft', 'Heat Gauge Anger Craft', 'kids'::resource_kind, 'A craft thermometer where a child marks how hot their anger feels and what helps cool it.', 'Use it to help a child notice and name rising anger.', array['Children']::text[], '30 minutes', 'The child colors a thermometer and puts a cooling idea at each level. The parent practices one with the child. Praise using the tool, not only the result.', '[{"id": "f0", "type": "textarea", "label": "Color my anger thermometer:"}, {"id": "f1", "type": "textarea", "label": "What my body does when it is hot:"}, {"id": "f2", "type": "textarea", "label": "Something that cools me down:"}, {"id": "f3", "type": "textarea", "label": "What I can say to my grown-up:"}, {"id": "f4", "type": "textarea", "label": "What I will try next time:"}]'::jsonb, array['anger management', 'feelings', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('ritual-map-and-time-log', 'Ritual Map and Time Log', 'worksheet'::resource_kind, 'A log of rituals, how long they take and what they protect against.', 'Use it to help a client see how much time rituals take.', array['Adults']::text[], 'One week', 'Keep the tone curious. The client records the ritual, the trigger, and the time spent. Look together for the smallest ritual to try shortening, without forcing.', '[{"id": "f0", "type": "textarea", "label": "The ritual:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "How long it took:"}, {"id": "f3", "type": "textarea", "label": "What I feared would happen:"}, {"id": "f4", "type": "textarea", "label": "What I noticed afterward:"}]'::jsonb, array['OCD', 'rituals', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('exposure-practice-planning-page', 'Exposure Practice Planning Page', 'cbt'::resource_kind, 'A page for planning one practice with a gradual response delay.', 'Use it to help a client plan a step with practice staying with doubt.', array['Adults']::text[], '30 minutes', 'Choose a step from the ladder and plan the practice details. Agree on how long to delay a ritual. Review after, noting the urge level over time rather than success or failure.', '[{"id": "f0", "type": "textarea", "label": "The step I will practice:"}, {"id": "f1", "type": "textarea", "label": "The ritual I will delay:"}, {"id": "f2", "type": "textarea", "label": "How long I will wait:"}, {"id": "f3", "type": "textarea", "label": "My urge level before and after:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['OCD', 'exposure', 'core CBT']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('doubt-talks-while-i-act-page', 'Doubt Talks While I Act Page', 'act'::resource_kind, 'A page for acting on values while doubt keeps talking.', 'Use it to help a client do what matters while doubt is present.', array['Adults']::text[], '25 minutes', 'Have the client name the doubt, then name the value and a small step. Not answering the doubt is the practice. Keep reassurance seeking in view and talk about it.', '[{"id": "f0", "type": "textarea", "label": "The doubt that is loud:"}, {"id": "f1", "type": "textarea", "label": "What I want to do instead:"}, {"id": "f2", "type": "textarea", "label": "The value behind it:"}, {"id": "f3", "type": "textarea", "label": "A step I can take:"}, {"id": "f4", "type": "textarea", "label": "How I will let doubt talk:"}]'::jsonb, array['OCD', 'uncertainty', 'values']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('urge-to-check-delay-card', 'Urge to Check Delay Card', 'dbt'::resource_kind, 'A card for delaying a checking urge with a breathing and distraction plan.', 'Use it to help a client wait out a checking urge.', array['Adults']::text[], '20 minutes', 'Practice short delays first and lengthen them. Pair with a soothing activity. Notice what the urge does if left alone.', '[{"id": "f0", "type": "textarea", "label": "The checking urge:"}, {"id": "f1", "type": "textarea", "label": "How long I will wait:"}, {"id": "f2", "type": "textarea", "label": "What I will do while waiting:"}, {"id": "f3", "type": "textarea", "label": "The urge after waiting:"}, {"id": "f4", "type": "textarea", "label": "What I will do next:"}]'::jsonb, array['OCD', 'urges', 'distress tolerance']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('worry-brain-boss-drawing-page', 'Worry Brain Boss Drawing Page', 'kids'::resource_kind, 'A drawing page where a child draws the bossy worry voice and a plan to talk back.', 'Use it to help a child separate themselves from a bossy worry voice.', array['Children']::text[], '30 minutes', 'The child draws the voice and a funny name for it. The parent learns not to join in with rituals and reassurance, and practices a friendly reply. Remember reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my worry boss:"}, {"id": "f1", "type": "textarea", "label": "What it tells me to do:"}, {"id": "f2", "type": "textarea", "label": "What I will say back:"}, {"id": "f3", "type": "textarea", "label": "Who helps me:"}, {"id": "f4", "type": "textarea", "label": "What I did instead:"}]'::jsonb, array['OCD', 'externalizing', 'drawing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('surge-timeline-notes-page', 'Surge Timeline Notes Page', 'worksheet'::resource_kind, 'A page for marking when a surge of panic rises, peaks and falls.', 'Use it to help a client see that a surge peaks and passes.', array['Adults']::text[], 'One week', 'After each surge the client sketches the curve and notes the time. Look for what happened just before and what the body did after. Keep language on the experience, not on a label.', '[{"id": "f0", "type": "textarea", "label": "What I was doing before:"}, {"id": "f1", "type": "textarea", "label": "What I felt first:"}, {"id": "f2", "type": "textarea", "label": "When it peaked:"}, {"id": "f3", "type": "textarea", "label": "When it eased:"}, {"id": "f4", "type": "textarea", "label": "What I noticed about the curve:"}]'::jsonb, array['panic attacks', 'body sensations', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('body-sensation-interpretation-page', 'Body Sensation Interpretation Page', 'cbt'::resource_kind, 'A page for listing sensations and alternative explanations.', 'Use it to help a client test frightening readings of body sensations.', array['Adults']::text[], '25 minutes', 'List sensations and the feared meaning, then add other plausible explanations. Remind the client to see a doctor for new physical concerns. Review which explanations fit best.', '[{"id": "f0", "type": "textarea", "label": "The sensation:"}, {"id": "f1", "type": "textarea", "label": "What I feared it meant:"}, {"id": "f2", "type": "textarea", "label": "Other explanations:"}, {"id": "f3", "type": "textarea", "label": "What happened:"}, {"id": "f4", "type": "textarea", "label": "How I will remind myself:"}]'::jsonb, array['panic attacks', 'predictions', 'thought record']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('letting-the-surge-pass-practice-page', 'Letting the Surge Pass Practice Page', 'act'::resource_kind, 'A page for allowing a surge to be there while doing something that matters.', 'Use it to help a client let a surge come and go.', array['Adults']::text[], '25 minutes', 'Practice making room for sensations in session. Choose a small activity to carry on during a surge. Debrief on what it was like to stay in place.', '[{"id": "f0", "type": "textarea", "label": "The sensation I made room for:"}, {"id": "f1", "type": "textarea", "label": "What I did while it was there:"}, {"id": "f2", "type": "textarea", "label": "What happened to it:"}, {"id": "f3", "type": "textarea", "label": "What I valued doing:"}, {"id": "f4", "type": "textarea", "label": "What I will try next:"}]'::jsonb, array['panic attacks', 'acceptance', 'willingness']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('longer-out-breath-practice-card', 'Longer Out-Breath Practice Card', 'dbt'::resource_kind, 'A card for slow exhale breathing practice at calm times and during a surge.', 'Use it to help a client rehearse slow breathing when calm.', array['Adults']::text[], '15 minutes', 'Practice at calm times first, with a longer out-breath. Do not use as a way to avoid sensations. If breathing is uncomfortable, adjust or pick another skill.', '[{"id": "f0", "type": "textarea", "label": "How I breathe when calm:"}, {"id": "f1", "type": "textarea", "label": "How I breathe in a surge:"}, {"id": "f2", "type": "textarea", "label": "My count in and out:"}, {"id": "f3", "type": "textarea", "label": "Where I will practice:"}, {"id": "f4", "type": "textarea", "label": "How it felt:"}]'::jsonb, array['panic attacks', 'distress tolerance', 'regulation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('calm-button-poster-craft', 'Calm Button Poster Craft', 'kids'::resource_kind, 'A poster craft where a child makes a calm button with steps to press.', 'Use it to help a child remember calming steps during a rush of fear.', array['Children']::text[], '30 minutes', 'The child makes a button poster with three steps and the parent practices them too. Use it when calm first. Remember reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my calm button:"}, {"id": "f1", "type": "textarea", "label": "Step one:"}, {"id": "f2", "type": "textarea", "label": "Step two:"}, {"id": "f3", "type": "textarea", "label": "Step three:"}, {"id": "f4", "type": "textarea", "label": "Who presses it with me:"}]'::jsonb, array['panic attacks', 'calming', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('family-routine-anchors-chart', 'Family Routine Anchors Chart', 'worksheet'::resource_kind, 'A chart naming a few daily routines and who does what.', 'Use it to help parents set predictable routines.', array['Adults']::text[], '30 minutes', 'Choose two or three anchors, such as mornings and bedtime, and write simple steps. Let children help design the chart. Review what worked and cut what did not.', '[{"id": "f0", "type": "textarea", "label": "The routine I want to start with:"}, {"id": "f1", "type": "textarea", "label": "The steps:"}, {"id": "f2", "type": "textarea", "label": "Who does what:"}, {"id": "f3", "type": "textarea", "label": "What may get in the way:"}, {"id": "f4", "type": "textarea", "label": "How we will celebrate:"}]'::jsonb, array['parenting', 'routines', 'family']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('parent-expectation-check-page', 'Parent Expectation Check Page', 'cbt'::resource_kind, 'A page for checking whether expectations of a child fit their age and mood.', 'Use it to help a parent tune expectations to the child.', array['Adults']::text[], '25 minutes', 'List an expectation that led to conflict and ask what a child of this age can do. Reword it. Keep it free of blame for the parent.', '[{"id": "f0", "type": "textarea", "label": "My expectation:"}, {"id": "f1", "type": "textarea", "label": "What happened:"}, {"id": "f2", "type": "textarea", "label": "What my child can manage:"}, {"id": "f3", "type": "textarea", "label": "A fairer version:"}, {"id": "f4", "type": "textarea", "label": "What I will try:"}]'::jsonb, array['parenting', 'thought record', 'expectations']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('calm-parent-values-practice-page', 'Calm Parent Values Practice Page', 'act'::resource_kind, 'A page connecting parent values to a small action during a hard moment.', 'Use it to help a parent act on values when stressed.', array['Adults']::text[], '25 minutes', 'Ask what kind of parent the client wants to be, then rehearse a short action for a hard moment. Notice feelings without acting on them.', '[{"id": "f0", "type": "textarea", "label": "A value I hold as a parent:"}, {"id": "f1", "type": "textarea", "label": "A hard moment:"}, {"id": "f2", "type": "textarea", "label": "What I feel then:"}, {"id": "f3", "type": "textarea", "label": "What I will do instead:"}, {"id": "f4", "type": "textarea", "label": "How I will repair if I slip:"}]'::jsonb, array['parenting', 'values', 'coping skills']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('parenting-partners-agreement-sheet', 'Parenting Partners Agreement Sheet', 'couples'::resource_kind, 'A sheet for two parents to agree on a few shared rules and responses.', 'Use it to help parents respond to a child consistently.', array['Couples']::text[], '40 minutes', 'Each parent fills in what they want, and they compare. Agree on a few shared rules and who takes the lead in a moment. Revisit in two weeks.', '[{"id": "f0", "type": "textarea", "label": "A rule we agree on:"}, {"id": "f1", "type": "textarea", "label": "How I respond now:"}, {"id": "f2", "type": "textarea", "label": "How we will respond together:"}, {"id": "f3", "type": "textarea", "label": "When I will step in:"}, {"id": "f4", "type": "textarea", "label": "When we will meet again:"}]'::jsonb, array['parenting', 'communication', 'family']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('praise-catch-game-for-families', 'Praise Catch Game for Families', 'game'::resource_kind, 'A game where family members catch each other doing something kind.', 'Use it to help families notice and name positive behavior.', array['Groups']::text[], '20 minutes', 'Players take turns naming something kind they saw. A parent starts. Keep it specific, not general. Debrief on how it felt to be noticed.', '[{"id": "f0", "type": "textarea", "label": "A kind thing I saw:"}, {"id": "f1", "type": "textarea", "label": "Who did it:"}, {"id": "f2", "type": "textarea", "label": "How I felt when noticed:"}, {"id": "f3", "type": "textarea", "label": "A kind thing I will do:"}, {"id": "f4", "type": "textarea", "label": "How we will play again:"}]'::jsonb, array['parenting', 'connection', 'play']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('rest-protection-plan-page', 'Rest Protection Plan Page', 'worksheet'::resource_kind, 'A plan for guarding stretches of sleep and rest for a new parent.', 'Use it to help a new parent line up support for rest.', array['Adults']::text[], '25 minutes', 'List who can cover which stretch, and what the client will let go of. If the client mentions thoughts of harming themselves or the baby, make a safety plan in session; 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "When I need rest most:"}, {"id": "f1", "type": "textarea", "label": "Who can cover:"}, {"id": "f2", "type": "textarea", "label": "What I will let go:"}, {"id": "f3", "type": "textarea", "label": "My plan if I cannot sleep:"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) if I feel unsafe:"}]'::jsonb, array['perinatal and postpartum', 'sleep', 'support']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('early-weeks-harsh-thought-rewrite-page', 'Early Weeks Harsh Thought Rewrite Page', 'cbt'::resource_kind, 'A page for rewriting harsh thoughts about parenting in the early weeks.', 'Use it to help a parent ease harsh self-judgment.', array['Adults']::text[], '25 minutes', 'Gather the harsh thought and look at what a friend would say. Write a more balanced line. Keep it warm and avoid minimizing.', '[{"id": "f0", "type": "textarea", "label": "The harsh thought:"}, {"id": "f1", "type": "textarea", "label": "How I feel:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}, {"id": "f4", "type": "textarea", "label": "What I did well today:"}]'::jsonb, array['perinatal and postpartum', 'self-talk', 'thought record']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('small-moments-of-connection-page', 'Small Moments of Connection Page', 'act'::resource_kind, 'A page for noticing small moments of presence with a baby or partner.', 'Use it to help a parent anchor in present moments.', array['Adults']::text[], '20 minutes', 'Ask the client to find two small moments a day and note them. Do not set standards for how it should feel. Review which moments were enjoyed.', '[{"id": "f0", "type": "textarea", "label": "A moment today:"}, {"id": "f1", "type": "textarea", "label": "What I noticed:"}, {"id": "f2", "type": "textarea", "label": "What I felt:"}, {"id": "f3", "type": "textarea", "label": "What was hard:"}, {"id": "f4", "type": "textarea", "label": "What I will notice tomorrow:"}]'::jsonb, array['perinatal and postpartum', 'mindfulness', 'connection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('sharing-the-nights-plan', 'Sharing the Nights Plan', 'couples'::resource_kind, 'A plan for two partners to share night duties and recovery time.', 'Use it to help partners divide the nights fairly.', array['Couples']::text[], '30 minutes', 'Each partner says how they are doing and what they can offer. Write a trial plan for a week. Review the plan and adjust, with no scorekeeping.', '[{"id": "f0", "type": "textarea", "label": "How I am doing:"}, {"id": "f1", "type": "textarea", "label": "What I can offer:"}, {"id": "f2", "type": "textarea", "label": "Our trial plan:"}, {"id": "f3", "type": "textarea", "label": "What we will drop:"}, {"id": "f4", "type": "textarea", "label": "When we will review:"}]'::jsonb, array['perinatal and postpartum', 'planning', 'sleep']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('gentle-self-soothing-corner-card', 'Gentle Self-Soothing Corner Card', 'dbt'::resource_kind, 'A card for planning small soothing steps during hard moments.', 'Use it to help a parent have easy soothing choices ready.', array['Adults']::text[], '20 minutes', 'Pick things that take two minutes or less, like a warm drink or a song. Practice one. Keep it realistic for days with little time.', '[{"id": "f0", "type": "textarea", "label": "A two minute comfort:"}, {"id": "f1", "type": "textarea", "label": "Where I will keep it:"}, {"id": "f2", "type": "textarea", "label": "What I will say to myself:"}, {"id": "f3", "type": "textarea", "label": "Who I can ask for help:"}, {"id": "f4", "type": "textarea", "label": "What I will try tonight:"}]'::jsonb, array['perinatal and postpartum', 'self-soothing', 'coping skills']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('evidence-of-worth-collection-page', 'Evidence of Worth Collection Page', 'worksheet'::resource_kind, 'A page for collecting things that show the client''s worth beyond achievements.', 'Use it to help a client gather broader evidence of value.', array['Adults']::text[], '25 minutes', 'Ask for qualities, acts of care and times the client mattered to someone. Read the list back aloud. Notice resistance and go slowly.', '[{"id": "f0", "type": "textarea", "label": "Qualities others see in me:"}, {"id": "f1", "type": "textarea", "label": "Times I showed care:"}, {"id": "f2", "type": "textarea", "label": "Times I mattered to someone:"}, {"id": "f3", "type": "textarea", "label": "What I find hard to believe:"}, {"id": "f4", "type": "textarea", "label": "What I will add this week:"}]'::jsonb, array['self-esteem', 'strengths', 'self-compassion']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('critic-voice-interview-sheet', 'Critic Voice Interview Sheet', 'cbt'::resource_kind, 'A page for questioning the critic''s voice and finding a fairer reply.', 'Use it to help a client examine where harsh self-talk comes from.', array['Adults']::text[], '25 minutes', 'Ask who the voice sounds like and what it wants. Write a reply that is fair, not forced. Practice saying it aloud.', '[{"id": "f0", "type": "textarea", "label": "What my critic says:"}, {"id": "f1", "type": "textarea", "label": "Whose voice it sounds like:"}, {"id": "f2", "type": "textarea", "label": "What it is trying to do:"}, {"id": "f3", "type": "textarea", "label": "A fair reply:"}, {"id": "f4", "type": "textarea", "label": "How I feel after:"}]'::jsonb, array['self-esteem', 'self-talk', 'self-criticism']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('self-compassion-break-practice-page', 'Self-Compassion Break Practice Page', 'act'::resource_kind, 'A page walking through noticing pain, common humanity and kind words.', 'Use it to help a client offer themselves kindness during a hard moment.', array['Adults']::text[], '20 minutes', 'Walk through the three steps and let the client pick words. Some clients feel uneasy at first. Offer a short version for daily use.', '[{"id": "f0", "type": "textarea", "label": "The hard moment:"}, {"id": "f1", "type": "textarea", "label": "What others might also feel:"}, {"id": "f2", "type": "textarea", "label": "Kind words I could say:"}, {"id": "f3", "type": "textarea", "label": "A kind gesture:"}, {"id": "f4", "type": "textarea", "label": "How I felt after:"}]'::jsonb, array['self-esteem', 'self-compassion', 'mindfulness']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('building-mastery-daily-step-card', 'Building Mastery Daily Step Card', 'dbt'::resource_kind, 'A card for choosing one small thing each day to do well.', 'Use it to help a client build a sense of competence.', array['Adults']::text[], '15 minutes', 'Choose tasks that are doable and name what was done. Keep a list. Review weekly and gradually raise the challenge.', '[{"id": "f0", "type": "textarea", "label": "Today''s step:"}, {"id": "f1", "type": "textarea", "label": "How I did it:"}, {"id": "f2", "type": "textarea", "label": "How I felt after:"}, {"id": "f3", "type": "textarea", "label": "What I learned:"}, {"id": "f4", "type": "textarea", "label": "Tomorrow''s step:"}]'::jsonb, array['self-esteem', 'mastery', 'emotion regulation']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('proud-of-me-poster-craft', 'Proud of Me Poster Craft', 'kids'::resource_kind, 'A poster craft where a child shows favorite things and strengths.', 'Use it to help a child show who they are with pride.', array['Children']::text[], '30 minutes', 'The child draws and decorates, and the parent adds one thing they love. Keep praise on effort and traits, not looks. Hang it up at home.', '[{"id": "f0", "type": "textarea", "label": "Draw me:"}, {"id": "f1", "type": "textarea", "label": "Things I like:"}, {"id": "f2", "type": "textarea", "label": "Things I am good at:"}, {"id": "f3", "type": "textarea", "label": "What my family loves about me:"}, {"id": "f4", "type": "textarea", "label": "A word that describes me:"}]'::jsonb, array['self-esteem', 'strengths', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('social-situation-step-ladder-page', 'Social Situation Step Ladder Page', 'worksheet'::resource_kind, 'A ladder of social situations from easiest to hardest.', 'Use it to help a client plan gradual steps.', array['Adults']::text[], '25 minutes', 'Build the ladder together and rate each rung. Pick a first step that is a stretch but doable. Review each step and what the client learned.', '[{"id": "f0", "type": "textarea", "label": "Easiest situation:"}, {"id": "f1", "type": "textarea", "label": "Middle situation:"}, {"id": "f2", "type": "textarea", "label": "Hardest situation:"}, {"id": "f3", "type": "textarea", "label": "The first step:"}, {"id": "f4", "type": "textarea", "label": "When I will try it:"}]'::jsonb, array['social anxiety', 'exposure', 'avoidance']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('after-the-event-replay-check-page', 'After the Event Replay Check Page', 'cbt'::resource_kind, 'A page for checking post-event replays against what happened.', 'Use it to help a client see what happened beyond the replay.', array['Adults']::text[], '25 minutes', 'Ask the client to write what they remember and what others did. Notice mind reading. Compare the replay with facts.', '[{"id": "f0", "type": "textarea", "label": "What I replay:"}, {"id": "f1", "type": "textarea", "label": "What I fear others thought:"}, {"id": "f2", "type": "textarea", "label": "What I actually know:"}, {"id": "f3", "type": "textarea", "label": "A fairer view:"}, {"id": "f4", "type": "textarea", "label": "What I will do instead:"}]'::jsonb, array['social anxiety', 'rumination', 'thinking traps']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('go-with-nerves-event-planner', 'Go With Nerves Event Planner', 'act'::resource_kind, 'A plan for going to an event with nerves present.', 'Use it to help a client attend events with anxiety along.', array['Adults']::text[], '25 minutes', 'Choose an event, name the nerves and the value. Plan how long to stay and one thing to try. Review without grading performance.', '[{"id": "f0", "type": "textarea", "label": "The event:"}, {"id": "f1", "type": "textarea", "label": "The nerves I expect:"}, {"id": "f2", "type": "textarea", "label": "Why it matters to me:"}, {"id": "f3", "type": "textarea", "label": "What I will try:"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself after:"}]'::jsonb, array['social anxiety', 'values', 'committed action']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('starting-a-conversation-script-card', 'Starting a Conversation Script Card', 'dbt'::resource_kind, 'A card of openers and follow-up questions for starting a chat.', 'Use it to help a client rehearse simple conversation openers.', array['Adults']::text[], '20 minutes', 'Practice a few openers in session. Use open questions and gentle exits. Let the client adapt wording.', '[{"id": "f0", "type": "textarea", "label": "An opener I will try:"}, {"id": "f1", "type": "textarea", "label": "A follow-up question:"}, {"id": "f2", "type": "textarea", "label": "How I can end politely:"}, {"id": "f3", "type": "textarea", "label": "Who I will try it with:"}, {"id": "f4", "type": "textarea", "label": "How it went:"}]'::jsonb, array['social anxiety', 'interpersonal effectiveness', 'communication']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('conversation-dice-game', 'Conversation Dice Game', 'game'::resource_kind, 'A group game of rolling a die to pick a question to ask a neighbor.', 'Use it to help a group practice small talk in a low pressure way.', array['Groups']::text[], '25 minutes', 'Make a list of light questions numbered for the die. Players can pass. Debrief on what felt easier or harder.', '[{"id": "f0", "type": "textarea", "label": "A question I asked:"}, {"id": "f1", "type": "textarea", "label": "A question I was asked:"}, {"id": "f2", "type": "textarea", "label": "What I noticed about my body:"}, {"id": "f3", "type": "textarea", "label": "What was easier than expected:"}, {"id": "f4", "type": "textarea", "label": "What I will try outside:"}]'::jsonb, array['social anxiety', 'communication', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('grief-waves-tracker-page', 'Grief Waves Tracker Page', 'worksheet'::resource_kind, 'A page for noting when waves of grief rise and what helped.', 'Use it to help a client see patterns in grief.', array['Adults']::text[], 'One week', 'Treat waves as natural. The client notes time, trigger and what helped. If the client mentions thoughts of ending their life, make a plan in session; 988 (call or text) is available.', '[{"id": "f0", "type": "textarea", "label": "When it came:"}, {"id": "f1", "type": "textarea", "label": "What set it off:"}, {"id": "f2", "type": "textarea", "label": "What I felt:"}, {"id": "f3", "type": "textarea", "label": "What helped:"}, {"id": "f4", "type": "textarea", "label": "988 (call or text) if I feel unsafe:"}]'::jsonb, array['grief and loss', 'remembering', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('should-have-thoughts-fair-look-page', 'Should Have Thoughts Fair Look Page', 'cbt'::resource_kind, 'A page for looking at should have thoughts after a loss.', 'Use it to help a client examine hindsight thoughts.', array['Adults']::text[], '25 minutes', 'List the thought, then what was known at the time. Write a gentler statement. Do not push toward closure.', '[{"id": "f0", "type": "textarea", "label": "The should have thought:"}, {"id": "f1", "type": "textarea", "label": "What I knew then:"}, {"id": "f2", "type": "textarea", "label": "What I did out of love:"}, {"id": "f3", "type": "textarea", "label": "A gentler view:"}, {"id": "f4", "type": "textarea", "label": "What I need now:"}]'::jsonb, array['grief and loss', 'guilt', 'thought record']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('living-with-love-and-loss-page', 'Living With Love and Loss Page', 'act'::resource_kind, 'A page for holding grief and love together and choosing a way to honor them.', 'Use it to help a client honor what mattered.', array['Adults']::text[], '25 minutes', 'Ask what the person or thing meant, and a small act to honor it. Allow tears. Let the client set the pace.', '[{"id": "f0", "type": "textarea", "label": "What mattered about them:"}, {"id": "f1", "type": "textarea", "label": "How grief shows up:"}, {"id": "f2", "type": "textarea", "label": "A way to honor them:"}, {"id": "f3", "type": "textarea", "label": "What I will do this week:"}, {"id": "f4", "type": "textarea", "label": "Who can join me:"}]'::jsonb, array['grief and loss', 'values', 'remembering']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('grieving-differently-talk-sheet', 'Grieving Differently Talk Sheet', 'couples'::resource_kind, 'A sheet for partners who grieve in different ways.', 'Use it to help partners understand different grief styles.', array['Couples']::text[], '40 minutes', 'Each partner shares how they grieve and what they need. Avoid judging. Agree on one way to support each other.', '[{"id": "f0", "type": "textarea", "label": "How I grieve:"}, {"id": "f1", "type": "textarea", "label": "What I need:"}, {"id": "f2", "type": "textarea", "label": "What I misunderstand about you:"}, {"id": "f3", "type": "textarea", "label": "One thing you can do:"}, {"id": "f4", "type": "textarea", "label": "One thing I can do:"}]'::jsonb, array['grief and loss', 'support', 'communication']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('memory-treasure-box-craft', 'Memory Treasure Box Craft', 'kids'::resource_kind, 'A craft box where a child keeps drawings and objects of someone they miss.', 'Use it to help a child hold memories in a safe place.', array['Children']::text[], '30 minutes', 'The child decorates a box and picks items. The parent shares a memory. Follow the child''s pace, and remember reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw something about them:"}, {"id": "f1", "type": "textarea", "label": "A favorite memory:"}, {"id": "f2", "type": "textarea", "label": "What I miss:"}, {"id": "f3", "type": "textarea", "label": "What I will put in the box:"}, {"id": "f4", "type": "textarea", "label": "Who I can talk to:"}]'::jsonb, array['grief and loss', 'remembering', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('complaint-into-request-rewrite-pairs', 'Complaint Into Request Rewrite Pairs', 'couples'::resource_kind, 'A sheet for turning complaints into positive requests.', 'Use it to help partners make requests instead of attacks.', array['Couples']::text[], '30 minutes', 'Each partner drafts a complaint, then a request. Share them and adjust. Keep requests specific and doable.', '[{"id": "f0", "type": "textarea", "label": "My complaint:"}, {"id": "f1", "type": "textarea", "label": "What I need underneath:"}, {"id": "f2", "type": "textarea", "label": "My request:"}, {"id": "f3", "type": "textarea", "label": "What I can offer:"}, {"id": "f4", "type": "textarea", "label": "What we agree on:"}]'::jsonb, array['relationship issues', 'communication', 'Gottman']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('four-horsemen-antidotes-practice-page', 'Four Horsemen Antidotes Practice Page', 'couples'::resource_kind, 'A page for noticing criticism and contempt and trying their antidotes.', 'Use it to help partners practice gentler ways of speaking.', array['Couples']::text[], '40 minutes', 'Name the patterns and their opposites, such as gentle start-up and appreciation. Role play one. Keep it kind and avoid blaming.', '[{"id": "f0", "type": "textarea", "label": "A pattern I notice:"}, {"id": "f1", "type": "textarea", "label": "Its antidote:"}, {"id": "f2", "type": "textarea", "label": "How I will try it:"}, {"id": "f3", "type": "textarea", "label": "How my partner can help:"}, {"id": "f4", "type": "textarea", "label": "How it went:"}]'::jsonb, array['relationship issues', 'conflict', 'Gottman']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('mind-reading-check-with-partner-page', 'Mind Reading Check With Partner Page', 'cbt'::resource_kind, 'A page for testing assumptions about a partner''s thoughts.', 'Use it to help a client check guesses before reacting.', array['Adults']::text[], '25 minutes', 'List the guess, rate belief, then plan to ask. Review what the partner said. Notice how often guesses were off.', '[{"id": "f0", "type": "textarea", "label": "My guess:"}, {"id": "f1", "type": "textarea", "label": "How sure I am:"}, {"id": "f2", "type": "textarea", "label": "What I will ask:"}, {"id": "f3", "type": "textarea", "label": "What they said:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['relationship issues', 'assumptions', 'communication']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('relationship-values-compass-page', 'Relationship Values Compass Page', 'act'::resource_kind, 'A page for naming values for a relationship and one step toward each.', 'Use it to help a client act on values even when it is tense.', array['Adults']::text[], '25 minutes', 'Ask what the client wants to bring to the relationship. Choose one step and a time. Review it next session.', '[{"id": "f0", "type": "textarea", "label": "A value I want in my relationship:"}, {"id": "f1", "type": "textarea", "label": "A recent moment I lived it:"}, {"id": "f2", "type": "textarea", "label": "A step this week:"}, {"id": "f3", "type": "textarea", "label": "What will get in the way:"}, {"id": "f4", "type": "textarea", "label": "What I will do:"}]'::jsonb, array['relationship issues', 'values', 'connection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('appreciation-pass-game-for-partners', 'Appreciation Pass Game for Partners', 'game'::resource_kind, 'A game of passing a token and sharing an appreciation.', 'Use it to help partners share specific appreciation.', array['Couples']::text[], '20 minutes', 'Partners pass a token back and forth, each time sharing one specific appreciation. Debrief on what felt good. Do not use during conflict.', '[{"id": "f0", "type": "textarea", "label": "An appreciation I gave:"}, {"id": "f1", "type": "textarea", "label": "One I received:"}, {"id": "f2", "type": "textarea", "label": "How it felt:"}, {"id": "f3", "type": "textarea", "label": "How we can do more:"}, {"id": "f4", "type": "textarea", "label": "When we will play again:"}]'::jsonb, array['relationship issues', 'appreciation', 'connection']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('support-rings-map-for-today', 'Support Rings Map for Today', 'worksheet'::resource_kind, 'A page for mapping trusted people and places at different distances.', 'Use it to help a client see who and what supports them.', array['Adults']::text[], '25 minutes', 'Do not ask for details of what happened. Focus on present supports and safety. Remember reporting duties where they apply, and go slowly.', '[{"id": "f0", "type": "textarea", "label": "People close to me I trust:"}, {"id": "f1", "type": "textarea", "label": "Places where I feel safe:"}, {"id": "f2", "type": "textarea", "label": "Groups or services I can reach:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell first:"}, {"id": "f4", "type": "textarea", "label": "One new support I could add:"}]'::jsonb, array['sexual abuse', 'support', 'safety']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('not-my-fault-fair-thought-page', 'Not My Fault Fair Thought Page', 'cbt'::resource_kind, 'A page for gently examining self-blame without retelling events.', 'Use it to help a client lessen self-blame.', array['Adults']::text[], '25 minutes', 'The client works only with present thoughts, not with details of events. Ask what they would say to a friend. Pace and stop if distress rises.', '[{"id": "f0", "type": "textarea", "label": "A thought I notice now:"}, {"id": "f1", "type": "textarea", "label": "How it feels:"}, {"id": "f2", "type": "textarea", "label": "What I would say to a friend:"}, {"id": "f3", "type": "textarea", "label": "A fairer thought:"}, {"id": "f4", "type": "textarea", "label": "How I will care for myself:"}]'::jsonb, array['sexual abuse', 'self-blame', 'pacing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('choice-and-control-values-page', 'Choice and Control Values Page', 'act'::resource_kind, 'A page for practicing choice in small daily matters.', 'Use it to help a client practice making choices.', array['Adults']::text[], '20 minutes', 'Choose small decisions and practice saying yes or no. Respect any hesitance. Keep events out of the work.', '[{"id": "f0", "type": "textarea", "label": "A choice I made today:"}, {"id": "f1", "type": "textarea", "label": "How my body felt:"}, {"id": "f2", "type": "textarea", "label": "A value behind it:"}, {"id": "f3", "type": "textarea", "label": "A choice I want to make:"}, {"id": "f4", "type": "textarea", "label": "Who supports me:"}]'::jsonb, array['sexual abuse', 'choice', 'values']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('here-and-now-senses-count-card', 'Here and Now Senses Count Card', 'dbt'::resource_kind, 'A card for returning to the present through the five senses.', 'Use it to help a client come back to now.', array['Adults']::text[], '15 minutes', 'Practice in calm moments first. Offer eyes open, and let the client choose what feels comfortable. Pair with a safety plan.', '[{"id": "f0", "type": "textarea", "label": "Five things I see:"}, {"id": "f1", "type": "textarea", "label": "Four things I hear:"}, {"id": "f2", "type": "textarea", "label": "Three things I feel:"}, {"id": "f3", "type": "textarea", "label": "Two things I smell:"}, {"id": "f4", "type": "textarea", "label": "One thing I taste:"}]'::jsonb, array['sexual abuse', 'grounding', 'pacing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('safe-grown-ups-and-body-rules-drawing', 'Safe Grown-Ups and Body Rules Drawing', 'kids'::resource_kind, 'A drawing where a child shows safe grown-ups and rules about their body.', 'Use it to help a child learn who to tell and that their body is theirs.', array['Children']::text[], '30 minutes', 'The child draws trusted people and says what to do if something feels wrong. Remember your reporting duties if a child discloses. The parent learns to listen and stay calm.', '[{"id": "f0", "type": "textarea", "label": "Draw my safe grown-ups:"}, {"id": "f1", "type": "textarea", "label": "Rules about my body:"}, {"id": "f2", "type": "textarea", "label": "What I can do if I feel unsafe:"}, {"id": "f3", "type": "textarea", "label": "Who I can tell:"}, {"id": "f4", "type": "textarea", "label": "How I feel now:"}]'::jsonb, array['sexual abuse', 'safety', 'drawing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('skill-fit-matching-chart', 'Skill Fit Matching Chart', 'worksheet'::resource_kind, 'A chart matching coping skills to situations and intensity.', 'Use it to help a client choose a skill that fits the moment.', array['Adults']::text[], '25 minutes', 'List situations and rate intensity, then match skills. Try a few in session. Retire any that do not work.', '[{"id": "f0", "type": "textarea", "label": "A situation:"}, {"id": "f1", "type": "textarea", "label": "Intensity, 0 to 10:"}, {"id": "f2", "type": "textarea", "label": "The skill that fits:"}, {"id": "f3", "type": "textarea", "label": "A backup:"}, {"id": "f4", "type": "textarea", "label": "How I will remember it:"}]'::jsonb, array['coping skills', 'toolbox', 'planning']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('helpful-thought-practice-cards', 'Helpful Thought Practice Cards', 'cbt'::resource_kind, 'A set of cards with coping thoughts to practice before a hard event.', 'Use it to help a client rehearse helpful self-talk.', array['Adults']::text[], '25 minutes', 'Write short statements in the client''s voice. Practice them aloud. Replace any that sound false. Review which cards the client reaches for.', '[{"id": "f0", "type": "textarea", "label": "A hard event:"}, {"id": "f1", "type": "textarea", "label": "My coping thought:"}, {"id": "f2", "type": "textarea", "label": "How I will say it:"}, {"id": "f3", "type": "textarea", "label": "A backup thought:"}, {"id": "f4", "type": "textarea", "label": "How I felt after:"}]'::jsonb, array['coping skills', 'coping statements', 'self-talk']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('workability-check-page', 'Workability Check Page', 'act'::resource_kind, 'A page asking whether a coping strategy works for the long run.', 'Use it to help a client check whether a strategy fits their values.', array['Adults']::text[], '25 minutes', 'List strategies and ask, does it move me toward what I value? Be curious, not critical. Keep ones that fit.', '[{"id": "f0", "type": "textarea", "label": "A strategy I use:"}, {"id": "f1", "type": "textarea", "label": "What it gives me:"}, {"id": "f2", "type": "textarea", "label": "What it costs:"}, {"id": "f3", "type": "textarea", "label": "Does it move me toward my values?"}, {"id": "f4", "type": "textarea", "label": "What I will keep or change:"}]'::jsonb, array['coping skills', 'workability', 'values']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('pleasant-events-plan-card', 'Pleasant Events Plan Card', 'dbt'::resource_kind, 'A card for scheduling pleasant events to build emotion resilience.', 'Use it to help a client add small pleasant events.', array['Adults']::text[], '20 minutes', 'Choose events that are easy and enjoyable. Schedule them. Notice mood and mindfulness of the event. Check in on what got done.', '[{"id": "f0", "type": "textarea", "label": "A pleasant event:"}, {"id": "f1", "type": "textarea", "label": "When I will do it:"}, {"id": "f2", "type": "textarea", "label": "Who with:"}, {"id": "f3", "type": "textarea", "label": "What I noticed:"}, {"id": "f4", "type": "textarea", "label": "What I will do next:"}]'::jsonb, array['coping skills', 'emotion regulation', 'self-soothing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('coping-skill-show-and-tell-game', 'Coping Skill Show and Tell Game', 'game'::resource_kind, 'A game where players demonstrate a skill and teach it to a neighbor.', 'Use it to help a group learn skills from each other.', array['Groups']::text[], '25 minutes', 'Each player picks a skill, demonstrates and teaches. Debrief on what to try. Allow pass. Debrief on what each player will try, and let anyone pass on a turn.', '[{"id": "f0", "type": "textarea", "label": "The skill I showed:"}, {"id": "f1", "type": "textarea", "label": "How it helps:"}, {"id": "f2", "type": "textarea", "label": "A skill I learned:"}, {"id": "f3", "type": "textarea", "label": "When I will try it:"}, {"id": "f4", "type": "textarea", "label": "Who I will teach:"}]'::jsonb, array['coping skills', 'group', 'teaching']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('fear-rating-practice-log', 'Fear Rating Practice Log', 'worksheet'::resource_kind, 'A log of fear ratings before, during and after a step.', 'Use it to help a client see fear change over practice.', array['Adults']::text[], 'One week', 'Rate fear at each point. Notice how it moves. Plan the next step from the log. Compare the ratings and plan the next step.', '[{"id": "f0", "type": "textarea", "label": "The step I practiced:"}, {"id": "f1", "type": "textarea", "label": "Fear before:"}, {"id": "f2", "type": "textarea", "label": "Fear during:"}, {"id": "f3", "type": "textarea", "label": "Fear after:"}, {"id": "f4", "type": "textarea", "label": "What I noticed:"}]'::jsonb, array['phobias', 'exposure', 'self-monitoring']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('feared-situation-prediction-test-page', 'Feared Situation Prediction Test Page', 'cbt'::resource_kind, 'A page for testing a prediction about a feared situation.', 'Use it to help a client test what would happen.', array['Adults']::text[], '25 minutes', 'Write the prediction and confidence, plan a safe test, record the outcome. Remind that the test is gradual and chosen by the client.', '[{"id": "f0", "type": "textarea", "label": "My prediction:"}, {"id": "f1", "type": "textarea", "label": "Confidence, 0 to 100:"}, {"id": "f2", "type": "textarea", "label": "The test:"}, {"id": "f3", "type": "textarea", "label": "What happened:"}, {"id": "f4", "type": "textarea", "label": "What I learned:"}]'::jsonb, array['phobias', 'predictions', 'behavioral experiment']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('bringing-fear-along-page', 'Bringing Fear Along Page', 'act'::resource_kind, 'A page for taking a step toward a valued goal with fear present.', 'Use it to help a client act on values with fear.', array['Adults']::text[], '25 minutes', 'Name a goal that fear blocks and a small step. Make room for fear. Review the step afterward. Check back on the step at the next visit.', '[{"id": "f0", "type": "textarea", "label": "A goal that fear blocks:"}, {"id": "f1", "type": "textarea", "label": "The fear I bring:"}, {"id": "f2", "type": "textarea", "label": "The step:"}, {"id": "f3", "type": "textarea", "label": "What I will do with the fear:"}, {"id": "f4", "type": "textarea", "label": "What happened:"}]'::jsonb, array['phobias', 'values', 'willingness']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('fear-friend-drawing-page', 'Fear Friend Drawing Page', 'kids'::resource_kind, 'A page where a child draws a feared thing as a friendly character.', 'Use it to help a child feel less scared of a feared thing.', array['Children']::text[], '30 minutes', 'The child draws and names the character. The parent joins in with a gentle approach step. Go at the child''s pace, and remember reporting duties if a child discloses harm.', '[{"id": "f0", "type": "textarea", "label": "Draw my fear as a character:"}, {"id": "f1", "type": "textarea", "label": "Its name:"}, {"id": "f2", "type": "textarea", "label": "What it wants:"}, {"id": "f3", "type": "textarea", "label": "A small brave step:"}, {"id": "f4", "type": "textarea", "label": "Who will be with me:"}]'::jsonb, array['phobias', 'externalizing', 'drawing']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('brave-path-spaces-board-game', 'Brave Path Spaces Board Game', 'game'::resource_kind, 'A board game where each space is a small step toward a feared thing.', 'Use it to help a group practice gradual steps in play.', array['Groups']::text[], '25 minutes', 'Make spaces with easy steps and let players choose. Cheer effort. Debrief on what was hard. Keep the pace gentle and let each player choose their space.', '[{"id": "f0", "type": "textarea", "label": "A step I took:"}, {"id": "f1", "type": "textarea", "label": "How it felt:"}, {"id": "f2", "type": "textarea", "label": "A step I want to try:"}, {"id": "f3", "type": "textarea", "label": "Who cheered me on:"}, {"id": "f4", "type": "textarea", "label": "What I will do next:"}]'::jsonb, array['phobias', 'exposure', 'group']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('body-gratitude-letter-page', 'Body Gratitude Letter Page', 'worksheet'::resource_kind, 'A page for writing thanks to the body for what it does.', 'Use it to help a client appreciate their body''s function.', array['Adults']::text[], '20 minutes', 'Focus on what the body does, not how it looks. Skip any measuring or comparing. Read the letter aloud if the client wishes.', '[{"id": "f0", "type": "textarea", "label": "Dear body, thank you for:"}, {"id": "f1", "type": "textarea", "label": "What I like doing with you:"}, {"id": "f2", "type": "textarea", "label": "A time you helped me:"}, {"id": "f3", "type": "textarea", "label": "How I will care for you:"}, {"id": "f4", "type": "textarea", "label": "What I want to say next:"}]'::jsonb, array['body image', 'appreciation', 'self-compassion']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('comparison-catch-page', 'Comparison Catch Page', 'cbt'::resource_kind, 'A page for noticing comparison thoughts and what they cost.', 'Use it to help a client catch comparison and respond.', array['Adults']::text[], '25 minutes', 'Note when and where comparison happens, and what it costs. Write a kinder reply. Consider limiting triggering media.', '[{"id": "f0", "type": "textarea", "label": "Where I compared:"}, {"id": "f1", "type": "textarea", "label": "What I told myself:"}, {"id": "f2", "type": "textarea", "label": "What it cost me:"}, {"id": "f3", "type": "textarea", "label": "A kinder reply:"}, {"id": "f4", "type": "textarea", "label": "What I will do instead:"}]'::jsonb, array['body image', 'self-talk', 'thinking traps']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('values-beyond-looks-practice-page', 'Values Beyond Looks Practice Page', 'act'::resource_kind, 'A page for choosing actions that follow values, whatever the mirror shows.', 'Use it to help a client live by values, not appearance.', array['Adults']::text[], '25 minutes', 'Ask what the client would do if looks did not matter. Pick one step. Review without grading. Keep the focus on what the client values.', '[{"id": "f0", "type": "textarea", "label": "What I would do if looks did not matter:"}, {"id": "f1", "type": "textarea", "label": "The value behind it:"}, {"id": "f2", "type": "textarea", "label": "A step this week:"}, {"id": "f3", "type": "textarea", "label": "What may get in the way:"}, {"id": "f4", "type": "textarea", "label": "How I will respond:"}]'::jsonb, array['body image', 'values', 'committed action']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('mindful-mirror-description-card', 'Mindful Mirror Description Card', 'dbt'::resource_kind, 'A card for describing without judgment what the mirror shows.', 'Use it to help a client describe neutrally.', array['Adults']::text[], '20 minutes', 'Practice describing with neutral words and noticing judgments. Keep it short. Let the client choose whether to use a mirror.', '[{"id": "f0", "type": "textarea", "label": "A neutral description:"}, {"id": "f1", "type": "textarea", "label": "A judgment I noticed:"}, {"id": "f2", "type": "textarea", "label": "How I let it pass:"}, {"id": "f3", "type": "textarea", "label": "What I felt:"}, {"id": "f4", "type": "textarea", "label": "What I will try:"}]'::jsonb, array['body image', 'mindfulness', 'nonjudgment']::text[], '2026-11-06T15:00:00+00:00'::timestamptz),
  ('my-body-does-amazing-things-collage', 'My Body Does Amazing Things Collage', 'kids'::resource_kind, 'A collage where a child shows what their body can do.', 'Use it to help a child focus on what their body does.', array['Children']::text[], '30 minutes', 'The child draws or cuts out pictures of actions. The parent adds one. Avoid comments on size or looks.', '[{"id": "f0", "type": "textarea", "label": "Draw something my body does:"}, {"id": "f1", "type": "textarea", "label": "My favorite movement:"}, {"id": "f2", "type": "textarea", "label": "What my body helps me do with friends:"}, {"id": "f3", "type": "textarea", "label": "A thank you to my body:"}, {"id": "f4", "type": "textarea", "label": "Who I will show:"}]'::jsonb, array['body image', 'appreciation', 'craft']::text[], '2026-11-06T15:00:00+00:00'::timestamptz)
